const b = $json.body || $json;
const a = (b.action || 'send').toLowerCase();
const chat = String(b.chat || b.contact || 'team-webman');
if (a === 'image' || a === 'photo') {
  return [{ json: { route: 'file', imageUrl: b.imageUrl || b.url || '', caption: b.caption || b.text || '', chat } }];
}
const args = ['--chat', chat];
if (a === 'send') args.push('send', '--text', b.text || '');
else if (a === 'send-file') args.push('send-file', '--path', b.path || '', '--caption', b.caption || '', '--kind', b.kind || 'photo');
else if (a === 'pin') args.push('pin', String(b.messageId));
else if (a === 'unpin') args.push('unpin', String(b.messageId || 'all'));
else if (a === 'poll') args.push('poll', '--question', b.question || '', '--options', (b.options || []).join(','));
else if (a === 'delete') args.push('delete', String(b.messageId));
else if (a === 'edit') args.push('edit', String(b.messageId), '--text', b.text || '');
else if (a === 'admins') args.push('admins');
else if (a === 'members') args.push('members');
else if (a === 'stats') args.push('stats');
else if (a === 'chat') args.push('chat');
else if (a === 'topics') args.push('topics', 'list');
else if (a === 'history') args.push('history', '--limit', String(b.limit || 10));
else if (a === 'read') args.push('read', '--limit', String(b.limit || 10));
else if (a === 'search') args.push('search', '--query', b.query || '', '--limit', String(b.limit || 10));
else if (a === 'updates') args.push('updates');
else args.push('send', '--text', '[hub] action inconnue: ' + a);
if (b.topic) args.push('--topic', String(b.topic));
if (b.reply) args.push('--reply', String(b.reply));
return [{ json: { route: 'cli', command: 'cli-anything-telegram', args, timeoutMs: 60000 } }];

